"""
App icon / 桌面图标(记忆银河)

给什么用
------------------------------------------------------------------
把 OB 面板 https://<域名>/dashboard 用 Safari「添加到主屏幕」之后,
iOS 会去抓 <link rel="apple-touch-icon"> 指的那张图当桌面图标。
图就在这个文件里(base64 的 PNG),由 server.py 的 /icon-*.png 路由吐出去。

为什么是 .py 而不是几个 .png 文件
------------------------------------------------------------------
和 galaxy_page.py 同一个理由:Zeabur 自动部署会沿用**缓存的旧构建计划**,
旧 Dockerfile 只有 `COPY *.py .` 和几行写死的 COPY —— 新增的二进制文件
进不了镜像,线上就是 404。放进 .py 模块,新旧构建计划都能到位。
(2026-08-29 那次 galaxy.html 排查见 ob-backup/SYSTEM-HANDBOOK.md §10。)

图案是什么
------------------------------------------------------------------
一片旋涡星系:核球是最亮的那团,两条旋臂由散落的星点组成,右上角一颗
独自的亮星。配色沿用面板的蓝白液态玻璃(#0A1836 → #1C3E84,星点
#96C4FF / #78E2FF / #CBB0FF)。生成脚本不入库 —— 图是成品,改图直接换
下面的 base64,或者让下一个 CC 重新画一张。

尺寸
------------------------------------------------------------------
  180 —— iPhone 的 apple-touch-icon(iOS 真正会用的那张)
  192 / 512 —— PWA manifest(Android / 桌面浏览器)
   32 —— 浏览器标签页的小图标
"""

